<?php

// 競馬情報取得の繋ぎ

class KeibaEx {

    const UMA_API_URL = "https://api.winsight.jp/keiba/api/json/";

    static public function extract($race_code) {
        if (empty($race_code)) $race_code = '';
        return [
            'nen' => substr($race_code, 0, 4),
            'tsuki' => substr($race_code, 4, 2),
            'hi' => substr($race_code, 6, 2),
            'keibajo' => substr($race_code, 8, 2),
            'kai' => substr($race_code, 10, 2),
            'nichime' => substr($race_code, 12, 2),
            'race_bango' => substr($race_code, 14, 2),

            'YYYYMMDD' => substr($race_code, 0, 8),
            'day' => substr($race_code, 0, 4) . '-' . substr($race_code, 4, 2) . '-' . substr($race_code, 6, 2),
            'kaisai_code' => substr($race_code, 0, 14),
            'race_code' => $race_code,
        ];

    }


    /**
     * 開催日程
     * @param $date
     * @return mixed
     * https://api2.winsight.jp/keiba/api/json/kaisai/kaisai.php?ym=[開催月：YYYYMM] ※def:アクセス当月
     */

