    /**
     * 開催日レース一覧
     * @param $date
     * @return mixed
     * https://api2.winsight.jp/keiba/api/json/race/racelist.php?date=[開催日：YYYYMMDD] ※def:アクセス当日
     */


    static
    public function getRaceList($YYYYMMDD) {
        $YYYYMMDD = str_replace('-', '', $YYYYMMDD);
        $kaisaiList = [];
        $RaceList = [];
        $data = gzip_get_contents(self::UMA_API_URL . 'race/racelist.php' . '?date=' . $YYYYMMDD);
        $data = json_decode($data, true);

        if (isset($data['keibajo'])) {
            foreach ($data['keibajo'] as $kaisai_code => $keibajo) {
                // レース情報
                $codes = self::extract($kaisai_code);
                if ($codes['YYYYMMDD'] === $YYYYMMDD) {
                    foreach ($keibajo['race'] as $race) {
                        $race_code = $race['race_code'];
                        $RaceList[$race_code] = $race;
                        $raceData = [
                            'race_code' => $race_code,
                            'day' => $codes['day'],
                            'place' => $codes['keibajo'],
                        ];
                        Race::writeRace($raceData, $race);
                    }
                    unset($keibajo['race']);

                    // 開催情報
                    $kaisaiList[$kaisai_code] = $keibajo;
                    $KaisaiData = [
                        'kaisai_code' => $kaisai_code,
                        'day' => $codes['day'],
                        'place' => $codes['keibajo'],
                    ];
                    Race::writeKaisai($KaisaiData, $keibajo);
                }
            }
        } else {
            //echo "NO DATA $YYYYMMDD `keibajo`\n";
            //var_dump($data);
        }
        return $RaceList;

    }

    /**
     * 馬柱
     * @param $race_code
     * @return mixed
     *
     * https://api2.winsight.jp/keiba/api/json/uma/umabashira.php?date=[開催日：YYYYMMDD]&jyo=[場所コード]&bango=[レース番号]
     */
    static function getUmabashira($race_code) {
        $codes = self::extract($race_code);
        $data = gzip_get_contents(self::UMA_API_URL . "uma/umabashira.php?date={$codes['nen']}{$codes['tsuki']}{$codes['hi']}&jyo={$codes['keibajo']}&bango={$codes['race_bango']}");
        $data = json_decode($data, true);

        // レース結果等
        $race_result = $data['race'];
        $race_code = $race_result['race_code'];
        $Race = Race::from('race_info')->where('race_code', $race_code)->first();
        if ($Race) {
            $Race->save(['result' => json_encode($race_result, JSON_UNESCAPED_UNICODE)], 'race_info');
        }

        // 馬情報保存
        $result = [];
        $umas = $data['uma'];
        $exists = [];
        foreach ($umas as $uma) {
            if (App::isLocal() && $uma['umaban'] === 0) {
                $uma['umaban'] = count($result) + 1;
            }
            $umaban = $uma['umaban'];
            $registration = $uma['ketto_toroku_bango'];
            Race::writeUma($race_code, $umaban, $registration, $uma);
            $result[$umaban] = $uma;
            $exists[] = $registration;
        }

        // いない馬を無効化
        $UmaList = Race::from('race_uma')->where('race_code', $race_code)->all();
        foreach ($UmaList as $Uma) {
            if (!in_array($Uma->registration, $exists)) {
                $Uma->save(['umaban' => -1], 'race_uma');
            }
        }

        return $result;
    }

